head.b:skin:
/* ==================== VARIABEL PREFERENSI ==================== */
/* Warna utama menggunakan Emerald Green sesuai tema QuranViz [cite: 314] */
<Variable name="primaryColor" description="Warna Utama" type="color" default="#10b981" value="#10b981"/>
<Variable name="secondaryColor" description="Warna Emas" type="color" default="#eab308" value="#eab308"/>
<Variable name="bodyBg" description="Background" type="color" default="#f8fafc" value="#f8fafc"/>

body {
  font-family: 'Segoe UI', system-ui, sans-serif; [cite: 316]
  background: $(bodyBg);
  color: #334155; [cite: 317]
  line-height: 1.7;
  margin: 0;
}

/* Layout Container [cite: 318, 319] */
.container {
  max-width: 680px;
  margin: 40px auto;
  padding: 40px 35px;
  background: #ffffff;
  border-radius: 28px;
  box-shadow: 0 20px 40px rgba(15, 23, 42, 0.08);
  border: 1px solid #d1fae5;
}

/* Gaya Card Ayat [cite: 331, 332] */
.quran-card {
  background: linear-gradient(135deg, #f0fdf4, #ecfdf5);
  padding: 30px;
  border-radius: 20px;
  border-left: 6px solid $(primaryColor);
}

.verse {
  background: #ffffff;
  margin-bottom: 25px;
  padding: 22px;
  border-radius: 16px;
  border-left: 5px solid $(primaryColor); [cite: 333]
}

.arabic {
  font-size: 1.65rem;
  line-height: 2.5;
  text-align: right;
  direction: rtl;
  color: #1e3a8a; [cite: 334]
}
